class State(TypedDict):
    question: str
    docs: list[str]
    answer: str

def generate(state: State) -> dict:
    # touches ONLY "answer"; question and docs are untouched
    return {"answer": llm.invoke(state["docs"])}

from pydantic import BaseModel, Field
from langchain_core.tools import tool

class Args(BaseModel):
    city: str = Field(description="City name, e.g. 'London'")
    unit: str = Field("c", description="'c' or 'f'")

@tool(args_schema=Args)
def weather(city: str, unit: str = "c") -> str:
    """Current weather for a city. Use for any weather question."""
    return fetch(city, unit)

import mlflow
mlflow.langchain.autolog()

@mlflow.trace(span_type="RETRIEVER")
def retrieve(q: str) -> list[str]:
    return store.similarity_search(q, k=5)

@mlflow.trace
def answer(q: str) -> str:
    return chain.invoke({"q": q, "docs": retrieve(q)})

def route(state: State) -> str:
    return "answer" if state["relevant"] else "rewrite_query"

builder.add_conditional_edges("grade_docs", route)

from langgraph.types import Send

def fan_out(state: State):
    return [Send("write_card", {"topic": t}) for t in state["topics"]]

def write_card(payload: dict) -> dict:
    return {"cards": [draft(payload["topic"])]}

builder.add_conditional_edges("plan", fan_out, ["write_card"])

from langgraph.types import interrupt, Command

def approve(state: State) -> dict:
    ok = interrupt({"plan": state["plan"]})   # pause here
    return {"approved": ok}

cfg = {"configurable": {"thread_id": "t1"}}
app.invoke({"plan": "delete 3 rows"}, cfg)  # stops, returns __interrupt__
app.invoke(Command(resume=True), cfg)      # ok == True

from langchain_core.exceptions import ModelRefusalError  # check exact import in your version

def call_model(state: State) -> dict:
    try:
        return {"messages": [llm.invoke(state["messages"])]}
    except ModelRefusalError as e:
        return {"refused": True, "reason": str(e)}
